import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    adj = defaultdict(list)

    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    MOD = 10**9 + 7

    total_product = 1

    # Iterate over all unordered pairs (s, t) with s < t
    for s in range(1, N + 1):
        for t in range(s + 1, N + 1):
            # Compute min-cut between s and t using Dinic's algorithm
            # Build flow network for this pair
            # Nodes: 1..N, source s, sink t

            capacity = [[0] * (N + 1) for _ in range(N + 1)]

            for u in range(1, N + 1):
                for v, w in adj[u]:
                    if u < v:
                        capacity[u][v] += w
                        capacity[v][u] += w

            # Dinic's Algorithm
            level = [0] * (N + 1)
            ptr = [0] * (N + 1)

            def bfs(source, sink):
                nonlocal level
                level = [-1] * (N + 1)
                level[source] = 0
                queue = [source]
                head = 0
                while head < len(queue):
                    u = queue[head]
                    head += 1
                    for v in range(1, N + 1):
                        if level[v] == -1 and capacity[u][v] > 0:
                            level[v] = level[u] + 1
                            queue.append(v)
                return level[sink] != -1

            def dfs(u, sink, pushed, current_level):
                if u == sink or pushed == 0:
                    return pushed
                for i in range(ptr[u], N + 1):
                    v = i
                    ptr[u] = v
                    if level[v] != current_level + 1 or capacity[u][v] == 0:
                        continue
                    tr = dfs(v, sink, min(pushed, capacity[u][v]), current_level + 1)
                    if tr == 0:
                        continue
                    capacity[u][v] -= tr
                    capacity[v][u] += tr
                    return tr
                return 0

            max_flow = 0
            while bfs(s, t):
                ptr = [0] * (N + 1)
                while True:
                    pushed = dfs(s, t, float('inf'), 0)
                    if pushed == 0:
                        break
                    max_flow += pushed

            if max_flow == 0:
                # Should not happen given problem statement says graph is connected
                # But if it did, separation number is 0, making product 0
                total_product = 0
                break
            else:
                total_product = (total_product * max_flow) % MOD

        if total_product == 0:
            break

    print(total_product)

if __name__ == '__main__':
    solve()
